using System;
using System.IO;
using System.Drawing;
using System.Windows.Forms;
using System.Collections.Generic;
using System.Web.Script.Serialization;
namespace PetBridge {
    sealed class TaskActivityReducer {
        readonly Dictionary<string,string> active=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
        public int Count {get{return active.Count;}}
        public bool Apply(string line,string path){if(line.IndexOf("task_started",StringComparison.Ordinal)<0&&line.IndexOf("task_complete",StringComparison.Ordinal)<0&&line.IndexOf("turn_aborted",StringComparison.Ordinal)<0&&line.IndexOf("task_failed",StringComparison.Ordinal)<0)return false;
            Dictionary<string,object> o;try{o=new JavaScriptSerializer{MaxJsonLength=32*1024*1024}.DeserializeObject(line) as Dictionary<string,object>;}catch{return false;}if(o==null||!o.ContainsKey("type")||Convert.ToString(o["type"])!="event_msg"||!o.ContainsKey("payload"))return false;var p=o["payload"] as Dictionary<string,object>;if(p==null||!p.ContainsKey("type")||!p.ContainsKey("turn_id"))return false;string type=Convert.ToString(p["type"]),id=Convert.ToString(p["turn_id"]);if(String.IsNullOrEmpty(id))return false;string before;active.TryGetValue(path,out before);
            if(type=="task_started")active[path]=id;else if((type=="task_complete"||type=="turn_aborted"||type=="task_failed")&&before==id)active.Remove(path);string after;active.TryGetValue(path,out after);return before!=after;
        }
        bool RestoreLine(string line,string path,HashSet<string> ended){if(line.IndexOf("task_started",StringComparison.Ordinal)<0&&line.IndexOf("task_complete",StringComparison.Ordinal)<0&&line.IndexOf("turn_aborted",StringComparison.Ordinal)<0&&line.IndexOf("task_failed",StringComparison.Ordinal)<0)return false;try{var o=new JavaScriptSerializer{MaxJsonLength=32*1024*1024}.DeserializeObject(line) as Dictionary<string,object>;if(o==null||!o.ContainsKey("type")||Convert.ToString(o["type"])!="event_msg")return false;var p=o["payload"] as Dictionary<string,object>;if(p==null||!p.ContainsKey("type")||!p.ContainsKey("turn_id")||String.IsNullOrEmpty(Convert.ToString(p["turn_id"])))return false;string type=Convert.ToString(p["type"]);if(type!="task_started"&&type!="task_complete"&&type!="turn_aborted"&&type!="task_failed")return false;string id=Convert.ToString(p["turn_id"]);if(type!="task_started"){ended.Add(id);return false;}if(!ended.Contains(id))Apply(line,path);return true;}catch{return false;}}
        public void Bootstrap(string path){try{if(File.GetLastWriteTimeUtc(path)<DateTime.UtcNow.AddHours(-12))return;
            // Walk backwards to the last lifecycle record, even when one long turn exceeds 4 MB.
            using(var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){var ended=new HashSet<string>();long end=f.Length;byte[] tail=new byte[0];while(end>0){int count=(int)Math.Min(1024*1024,end);end-=count;var bytes=new byte[count+tail.Length];f.Position=end;int read=0;while(read<count){int n=f.Read(bytes,read,count-read);if(n==0)break;read+=n;}Buffer.BlockCopy(tail,0,bytes,count,tail.Length);int last=bytes.Length;for(int i=bytes.Length-1;i>=0;i--)if(bytes[i]==10){if(last>i+1&&RestoreLine(System.Text.Encoding.UTF8.GetString(bytes,i+1,last-i-1),path,ended))return;last=i;}if(end==0){if(last>0)RestoreLine(System.Text.Encoding.UTF8.GetString(bytes,0,last),path,ended);return;}tail=new byte[last];Buffer.BlockCopy(bytes,0,tail,0,last);}}
        }catch(IOException){}catch(UnauthorizedAccessException){}}
    }
    sealed class TaskBadge : AlphaForm {
        readonly PetForm pet;readonly Timer timer=new Timer();int phase;bool dragging;Point start;int ox,oy;
        public TaskBadge(PetForm p){pet=p;Text="搭档 · 任务进行中";Size=new Size(100,150);Cursor=Cursors.SizeAll;timer.Interval=160;timer.Tick+=delegate{phase=(phase+1)%9;Invalidate();};timer.Start();MouseDown+=delegate(object s,MouseEventArgs e){if(e.Button==MouseButtons.Right){pet.OpenSettings();return;}dragging=true;Capture=true;start=Cursor.Position;ox=pet.IsDocked?pet.Settings.DockActivityGap:pet.Settings.ActivityOffsetX;oy=pet.IsDocked?pet.Settings.DockActivityOffsetY:pet.Settings.ActivityOffsetY;};MouseMove+=delegate{if(!dragging)return;var delta=new Size(Cursor.Position.X-start.X,Cursor.Position.Y-start.Y);if(pet.IsDocked){pet.Settings.DockActivityGap=Math.Max(-20,Math.Min(80,ox+(pet.DockSide=="left"?delta.Width:-delta.Width)));pet.Settings.DockActivityOffsetY=Math.Max(-300,Math.Min(300,oy+delta.Height));}else{pet.Settings.ActivityOffsetX=Math.Max(-240,Math.Min(240,ox+delta.Width));pet.Settings.ActivityOffsetY=Math.Max(-300,Math.Min(300,oy+delta.Height));}Place();};MouseUp+=delegate{dragging=false;Capture=false;pet.ApplySettings();};FormClosed+=delegate{timer.Stop();timer.Dispose();};}
        public void Place(){var a=Screen.FromControl(pet).WorkingArea;var s=pet.Settings;float scale=(float)Math.Max(.5,Math.Min(1.5,s.ActivityScale));Size=new Size((int)Math.Round(28*scale)+72,(int)Math.Round(78*scale)+72);var body=pet.CharacterBounds;bool right=pet.IsDocked?pet.DockSide=="left":s.ActivitySide=="right"||s.ActivitySide=="auto"&&body.Right+46<a.Right;int gap=pet.IsDocked?s.DockActivityGap:s.ActivityGap;int x=right?body.Right+gap-36:body.Left-gap-(Width-72)-36;int y=body.Top+body.Height/2-Height/2;Location=new Point(Math.Max(a.Left-30,Math.Min(x+(pet.IsDocked?0:s.ActivityOffsetX),a.Right-Width+30)),Math.Max(a.Top-30,Math.Min(y+(pet.IsDocked?s.DockActivityOffsetY:s.ActivityOffsetY),a.Bottom-Height+30)));Invalidate();}
        protected override void PaintSurface(Graphics g){float scale=(float)Math.Max(.5,Math.Min(1.5,pet.Settings.ActivityScale));Bubble(g,new RectangleF(36,36,Width-72,Height-72),(Width-72)/2f,pet.Settings);for(int i=0;i<3;i++){int distance=(phase-i*3+9)%9;int alpha=distance<3?240:distance<6?140:65;using(var b=new SolidBrush(Color.FromArgb(alpha,112,112,112)))g.FillEllipse(b,36+(Width-72)/2f-3*scale,36+(16+i*18)*scale,6*scale,6*scale);}}
    }
    sealed class DockQuotaCard : AlphaForm {
        readonly PetForm pet;
        public DockQuotaCard(PetForm p){pet=p;Text="搭档 · 贴边额度";Size=new Size(302,112);MouseDown+=delegate(object s,MouseEventArgs e){if(e.Button==MouseButtons.Right)pet.OpenSettings();};}
        public void Place(){var a=Screen.FromControl(pet).WorkingArea;if(!pet.IsDocked){int top=pet.ComposerVisible?pet.ComposerBottom:pet.Top+pet.ToolbarBottom;Location=new Point(Math.Max(a.Left-24,Math.Min(pet.Left+pet.Width/2-Width/2,a.Right-Width+24)),top+pet.Settings.UsageGap-36);Invalidate();return;}bool below=pet.Settings.DockQuotaBelow||pet.Top< a.Top+64;int x=pet.DockSide=="left"?a.Left-24:a.Right-Width+24;int y=below?pet.Bottom+6-36:pet.Top-40-6-36;Location=new Point(x,Math.Max(a.Top-26,Math.Min(y,a.Bottom-Height+26)));Invalidate();}
        protected override void PaintSurface(Graphics g){Bubble(g,new RectangleF(36,36,230,40),20,pet.Settings);var snap=pet.Usage.Snapshot;string text=snap==null?"正在读取额度…":"5 小时 "+(snap.Primary==null?"—":snap.Primary.Remaining.ToString("0")+"%")+"  ·  本周 "+(snap.Secondary==null?"—":snap.Secondary.Remaining.ToString("0")+"%");if(pet.Usage.LastError&&snap!=null)text="上次："+text;using(var f=new Font("Microsoft YaHei UI",9))using(var b=new SolidBrush(Design.Ink))using(var format=new StringFormat{Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center,FormatFlags=StringFormatFlags.NoWrap})g.DrawString(text,f,b,new RectangleF(43,36,216,40),format);}
    }
}
